CREATE TABLE IF NOT EXISTS bandara (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(255) NOT NULL,
  iata VARCHAR(10),
  icao VARCHAR(10),
  kota VARCHAR(100),
  provinsi VARCHAR(100),
  jenis VARCHAR(50)
);


CREATE INDEX idx_bandara_iata ON bandara(iata);
CREATE INDEX idx_bandara_provinsi ON bandara(provinsi);
CREATE INDEX idx_bandara_jenis ON bandara(jenis);